CREATE TABLE IF NOT EXISTS public.lab_critical_ranges ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, test_code TEXT NOT NULL, test_name TEXT NOT NULL, critical_low NUMERIC, critical_high NUMERIC, warning_low NUMERIC, warning_high NUMERIC, unit_of_measure TEXT, age_group TEXT, gender TEXT, is_active BOOLEAN DEFAULT TRUE, notes TEXT, created_by UUID NOT NULL REFERENCES profiles(id), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now(), UNIQUE(hospital_id, test_code, age_group, gender) ); ALTER TABLE public.lab_critical_ranges ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "lab_critical_ranges_hospital_scope" ON lab_critical_ranges; CREATE POLICY "lab_critical_ranges_hospital_scope" ON public.lab_critical_ranges USING (hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid())); DROP POLICY IF EXISTS "lab_critical_ranges_insert" ON lab_critical_ranges; CREATE POLICY "lab_critical_ranges_insert" ON public.lab_critical_ranges FOR INSERT WITH CHECK ( hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid()) AND auth.uid() IN ( SELECT ur.user_id FROM user_roles ur WHERE ur.role IN ('admin', 'doctor') ) ); CREATE INDEX IF NOT EXISTS idx_lab_critical_ranges_hospital_test ON public.lab_critical_ranges(hospital_id, test_code, age_group); DROP TRIGGER IF EXISTS lab_critical_ranges_moddatetime ON public.lab_critical_ranges; CREATE TRIGGER lab_critical_ranges_moddatetime BEFORE UPDATE ON public.lab_critical_ranges FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at();